local function validChoice(value)
    return value == "auto" or value == "deDE" or value == "enUS"
end
function Localization.Initialize(saved)
    preferences = type(saved) == "table" and saved or {}
    if not validChoice(preferences.language) then preferences.language = "auto" end
end
function Localization.Set(choice)
    if not validChoice(choice) then return false end
    preferences.language = choice
    for _, label in ipairs(labels) do
        label.update(Localization.Text(label.key))
    end
    return true
end
function Localization.Choice() return preferences.language end

-- Locale reads are optional and fail closed to English. Other client languages
-- deliberately use English; this is an addon preference, never a client mutation.
function Localization.Locale()
    if preferences.language == "deDE" or preferences.language == "enUS" then return preferences.language end
    if type(GetLocale) == "function" then
        local ok, locale = pcall(GetLocale)
        if ok and locale == "deDE" then return "deDE" end
    end
    return "enUS"
end
function Localization.Text(key)
    if Localization.Locale() == "deDE" then return key end
    return Localization.English[key] or key
end

-- Only addon-owned labels register here; no Blizzard/global string method changes.
-- Remember source keys so an open window can switch language without rebuilding
-- frames, changing focus, casting or reloading the client.
function Localization.Key(key)
    for source, translated in pairs(Localization.English) do
        if translated == key then key = source; break end
    end
    return key
end
function Localization.Bind(update, key)
    labels[#labels + 1] = {update = update, key = Localization.Key(key)}
end
